const listFoods = `-- name: ListFoods :many
SELECT f.id, f.edition_id, f.subgroup_id, f.code, f.name, f.food_state, f.edible_pct, f.density_g_per_ml, f.basis_quantity, f.basis_unit, f.energy_kcal, f.protein_g, f.carbohydrates_g, f.lipids_g, f.fiber_g, f.equiv_reference_grams, f.equiv_value, f.tags, f.source_reference, f.status, sg.code AS subgroup_code, g.id AS group_id, count(*) OVER () AS total
FROM smae_foods f
JOIN smae_food_subgroups sg ON sg.id = f.subgroup_id
JOIN smae_food_groups g ON g.id = sg.group_id
WHERE f.edition_id = $1
  AND f.status = 'active'
  AND ($2::uuid = '00000000-0000-0000-0000-000000000000'::uuid OR g.id = $2::uuid)
  AND ($3::text = '' OR unaccent(f.name || ' ' || array_to_string(f.tags, ' ')) ILIKE '%' || unaccent($3::text) || '%')
ORDER BY lower(f.name), f.id
LIMIT $5::int OFFSET $4::int
`

type ListFoodsParams struct {
	EditionID  uuid.UUID `json:"edition_id"`
	GroupID    uuid.UUID `json:"group_id"`
	Search     string    `json:"search"`
	PageOffset int32     `json:"page_offset"`
	PageLimit  int32     `json:"page_limit"`
}

type ListFoodsRow struct {
	SmaeFood     SmaeFood  `json:"smae_food"`
	SubgroupCode string    `json:"subgroup_code"`
	GroupID      uuid.UUID `json:"group_id"`
	Total        int64     `json:"total"`
}

// Búsqueda sin acentos, filtro por grupo y paginación (carga progresiva, §20.2).
func (q *Queries) ListFoods(ctx context.Context, arg ListFoodsParams) ([]ListFoodsRow, error) {
	rows, err := q.db.Query(ctx, listFoods,
		arg.EditionID,
		arg.GroupID,
		arg.Search,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListFoodsRow
	for rows.Next() {
		var i ListFoodsRow
		if err := rows.Scan(
			&i.SmaeFood.ID,
			&i.SmaeFood.EditionID,
			&i.SmaeFood.SubgroupID,
			&i.SmaeFood.Code,
			&i.SmaeFood.Name,
			&i.SmaeFood.FoodState,
			&i.SmaeFood.EdiblePct,
			&i.SmaeFood.DensityGPerMl,
			&i.SmaeFood.BasisQuantity,
			&i.SmaeFood.BasisUnit,
			&i.SmaeFood.EnergyKcal,
			&i.SmaeFood.ProteinG,
			&i.SmaeFood.CarbohydratesG,
			&i.SmaeFood.LipidsG,
			&i.SmaeFood.FiberG,
			&i.SmaeFood.EquivReferenceGrams,
			&i.SmaeFood.EquivValue,
			&i.SmaeFood.Tags,
			&i.SmaeFood.SourceReference,
			&i.SmaeFood.Status,
			&i.SubgroupCode,
			&i.GroupID,
			&i.Total,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

